    """Measure the actual new contract's wire shape without admission or calls."""
    envelope = packet["contract"]["review_envelope"]
        + f"\nexact ending {index}  \n"
        for index in range(3)
    ]
    packet = {
        "receipts": [
            {
                "id": f"receipt_original_id_{index}",
                "tool_name": "file_read",
                "output": {
                    "content": source,
                    "sha256": hashlib.sha256(source.encode()).hexdigest(),
                    "other_original_value": {"review_source_ref": "untrusted original data"},
                },
            }
            for index, source in enumerate(sources)
