const result=await tools.exec_command({cmd:"@'
from pathlib import Path
from datetime import datetime,timezone
import xml.etree.ElementTree as ET
import hashlib,json,re
root=Path.cwd()
def hashed(relative):
 p=root/relative
 return {'path':relative,'sha256':hashlib.sha256(p.read_bytes()).hexdigest()}
def read_suite(relative):
 tree=ET.parse(root/relative); suites=tree.findall('.//testsuite'); cases=tree.findall('.//testcase'); statuses={}; failures={}
 for case in cases:
  key=case.attrib['classname']+'::'+case.attrib['name']
  fail=case.find('failure'); error=case.find('error'); skipped=case.find('skipped')
  state='failed' if fail is not None else 'error' if error is not None else 'skipped' if skipped is not None else 'passed'
  statuses[key]=state
  if fail is not None or error is not None:
   item=fail if fail is not None else error
   failures[key]={'message':item.attrib.get('message',''),'diagnostic_sha256':hashlib.sha256((item.text or '').encode()).hexdigest()}
 summary={key:sum(int(s.attrib.get(key,0)) for s in suites) for key in ('tests','failures','errors','skipped')}
 summary['passed']=summary['tests']-summary['failures']-summary['errors']-summary['skipped'];summary['xml_seconds']=sum(float(s.attrib.get('time',0)) for s in suites)
 assert summary['tests']==len(cases) and summary['failures']==sum(s=='failed' for s in statuses.values())
 return {**hashed(relative),'summary':summary,'failure_case_ids':sorted(failures)},statuses,failures
baseline,base_status,base_fail=read_suite('docs/audit/superagent/capability-backend-final.xml')
repair,repair_status,repair_fail=read_suite('docs/audit/superagent/capability-repair-backend.xml')
previous,prev_status,prev_fail=read_suite('docs/audit/superagent/capability-final-backend.xml')
current,cur_status,cur_fail=read_suite('docs/audit/superagent/capability-completion-backend.xml')
assert len(base_fail)==len(repair_fail)==13 and base_fail.keys()==repair_fail.keys()
assert len(prev_fail)==14 and len(cur_fail)==13
freeze_path='docs/audit/superagent/capability-completion-round1-source-freeze.json';freeze=json.loads((root/freeze_path).read_text(encoding='utf-8'));mismatches=[]
for item in freeze['files']:
 p=root/item['path']
 if not p.is_file() or hashlib.sha256(p.read_bytes()).hexdigest()!=item['sha256']:
  mismatches.append(item['path'])
assert len(freeze['files'])==354
same=sorted(base_fail.keys() & cur_fail.keys())
changed=[{'case_id':key,'baseline_message':base_fail[key]['message'],'current_message':cur_fail[key]['message']} for key in same if base_fail[key]['message']!=cur_fail[key]['message']]
log_path='.local/superagent/capability-completion-backend.log';log=(root/log_path).read_text(encoding='utf-8');summary_line=next(line.strip() for line in reversed(log.splitlines()) if re.search(r'\d+ failed, \d+ passed',line))
old_specialist='tests.test_specialist_artifact_projection::test_extra_specialist_artifact_respects_unchanged_raw_packet_cap'
replacement='tests.test_specialist_artifact_projection::test_extra_specialist_artifact_keeps_complete_evidence_and_native_admission_limits'
replacement_cases=[{'case_id':key,'current_status':status} for key,status in cur_status.items() if key.startswith(replacement)]
audit={'schema_version':1,'created_at':datetime.now(timezone.utc).isoformat(),'audit_type':'independent_programmatic_read_only_regression_comparison','scope':'Round 1 completion freeze only; this is not a full-suite result for later source corrections or freezes.','result':'historical_failure_set_unchanged_no_new_failed_cases','real_provider_calls_performed':0,'backend_or_wrapper_files_modified_by_this_audit':False,'old_xml_modified':False,'historical_baseline':baseline,'historical_corroborrating_suite':repair,'previous_full_suite_original_result':previous,'current_full_suite':{**current,'log':hashed(log_path),'pytest_summary_line':summary_line,'warning_count_from_summary':1},'current_source_binding':{**hashed(freeze_path),'file_count':len(freeze['files']),'all_frozen_files_match_at_audit':not mismatches,'mismatched_paths':mismatches,'binding_note':'The full-suite result belongs to this exact 354-file freeze. Any later source change requires separately bound validation and must not inherit this result.'},'comparison_against_historical_13':{'same_failed_case_ids':same,'new_failed_case_ids':sorted(cur_fail.keys()-base_fail.keys()),'historical_no_longer_failed':[{'case_id':key,'current_status':cur_status.get(key,'not_collected')} for key in sorted(base_fail.keys()-cur_fail.keys())],'failure_messages_unchanged':len(same)-len(changed),'changed_failure_messages':changed,'exact_failure_diagnostic_text_hash_changes':[{'case_id':key,'baseline_sha256':base_fail[key]['diagnostic_sha256'],'current_sha256':cur_fail[key]['diagnostic_sha256'],'note':'Full pytest diagnostics include temporary paths and run-specific context; message comparisons are reported separately.'} for key in same if base_fail[key]['diagnostic_sha256']!=cur_fail[key]['diagnostic_sha256']]},'comparison_against_original_14':{'new_failed_case_ids':sorted(cur_fail.keys()-prev_fail.keys()),'previous_no_longer_failed':[{'case_id':key,'current_status':cur_status.get(key,'not_collected')} for key in sorted(prev_fail.keys()-cur_fail.keys())],'old_specialist_contract_followup':{'previous_case_id':old_specialist,'previous_status':prev_status[old_specialist],'current_old_case_status':cur_status.get(old_specialist,'not_collected'),'replacement_cases':replacement_cases,'followup_evidence':hashed('docs/audit/superagent/capability-specialist-legacycap-followup-audit.json'),'interpretation':'The old 65K implicit-cap assertion was migrated in a separately recorded test-only followup. The original 2795 passed / 14 failed / 3 skipped XML remains unchanged, not rewritten as a 13-failure result.'}},'current_failure_records':[{'xml_case_id':key,'pytest_node_id':'backend/'+key.split('::',1)[0].replace('.','/')+'.py::'+key.split('::',1)[1],**cur_fail[key]} for key in sorted(cur_fail)],'current_skipped_cases':[key for key,state in cur_status.items() if state=='skipped'],'acceptance_boundary':'2853 passing tests with 13 historical failures is not a full test pass and establishes no real-task or Provider acceptance. Mock, programmatic and real Provider results remain separate.'}
print(json.dumps(audit,ensure_ascii=False))
'@ | backend/.venv/Scripts/python.exe -",workdir:"D:\Competition_this\Agent",max_output_tokens:17000}); 
if(result.exit_code!==0){text(result);exit();}
const audit=JSON.parse(result.output);
const body=JSON.stringify(audit,null,2);
